{
  "implementation": "def solve(case):
    lengths = case.get('lengths')
    scores = case.get('scores')
    budget = case.get('budget')
    if not isinstance(lengths, list) or not isinstance(scores, list):
        raise ValueError('lengths and scores must be lists')
    if len(lengths) != len(scores):
        raise ValueError('lengths and scores must have same length')
    if not isinstance(budget, int) or budget < 0:
        raise ValueError('budget must be a non-negative integer')
    n = len(lengths)
    # DP: list of best (score, weight, indices) for exact capacity w
    dp = [None] * (budget + 1)
    dp[0] = (0.0, 0, [])

    def better(a, b):
        # returns True if a is better than b
        if a[0] != b[0]:
            return a[0] > b[0]
        if a[1] != b[1]:
            return a[1] < b[1]
        # lexicographic compare indices (both sorted ascending)
        ixa, ixb = a[2], b[2]
        for x, y in zip(ixa, ixb):
            if x != y:
                return x < y
        return len(ixa) < len(ixb)  # shorter list if all equal

    for i in range(n):
        w_i = lengths[i]
        v_i = scores[i]
        newdp = dp[:]  # copy list of references
        for w in range(budget + 1):
            if dp[w] is None:
                continue
            if w + w_i <= budget:
                prev = dp[w]
                new_score = prev[0] + v_i
                new_weight = prev[1] + w_i
                new_indices = prev[2] + [i]
                new_state = (new_score, new_weight, new_indices)
                cur = newdp[w + w_i]
                if cur is None or better(new_state, cur):
                    newdp[w + w_i] = new_state
        dp = newdp

    best = None
    for w in range(budget + 1):
        if dp[w] is not None:
            if best is None or better(dp[w], best):
                best = dp[w]
    if best is None:
        # should not happen because dp[0] exists
        raise ValueError('No feasible selection')
    selected_indices = best[2]
    used_tokens = best[1]
    summed_score = best[0]
    return {
        'selected_indices': selected_indices,
        'used_tokens': used_tokens,
        'summed_score': summed_score
    }"
}
